<?php

declare(strict_types=1);

namespace Socly\Core\Addon;

/**
 * Public keys used to verify add-on licences and packages.
 *
 * The file bootstrap/addons_keys.php is generated by the private add-on tooling and
 * contains **only** public keys: losing the private counterparts is the only real risk.
 */
final class AddonKeys
{
    /** @return array<string, array{kid?:string, public_key?:string}> */
    public static function all(): array
    {
        $inline = trim((string) ($_ENV['SOCLY_ADDON_PUBLIC_KEYS'] ?? ''));
        if ($inline !== '') {
            $decoded = json_decode($inline, true);
            if (is_array($decoded)) {
                return $decoded;
            }
        }
        $file = trim((string) ($_ENV['SOCLY_ADDON_PUBLIC_KEYS_FILE'] ?? ''));
        if ($file === '') {
            $file = dirname(__DIR__, 3) . '/bootstrap/addons_keys.php';
        }
        if (!is_file($file)) {
            return [];
        }
        $keys = require $file;

        return is_array($keys) ? $keys : [];
    }

    /** Raw Ed25519 public key bytes for the given use ("license" or "package"). */
    public static function publicKey(string $use): string
    {
        $entry = self::all()[$use] ?? null;
        $encoded = is_array($entry) ? (string) ($entry['public_key'] ?? '') : '';

        return self::b64uDecode($encoded);
    }

    public static function kid(string $use): string
    {
        $entry = self::all()[$use] ?? null;

        return is_array($entry) ? (string) ($entry['kid'] ?? '') : '';
    }

    public static function b64u(string $raw): string
    {
        return rtrim(strtr(base64_encode($raw), '+/', '-_'), '=');
    }

    public static function b64uDecode(string $value): string
    {
        $value = strtr(trim($value), '-_', '+/');
        $pad = strlen($value) % 4;
        if ($pad > 0) {
            $value .= str_repeat('=', 4 - $pad);
        }
        $raw = base64_decode($value, true);

        return is_string($raw) ? $raw : '';
    }
}
